import{api,money,esc,paymentCard,paymentFeedback}from'/config.mjs';
const app=document.querySelector('#sponsor-app');let catalog=null,timer;
const UFS='AC AL AP AM BA CE DF ES GO MA MT MS MG PA PB PR PE PI RJ RN RS RO RR SC SP SE TO'.split(' ');
let selectedCity='',selectedUF='';try{const choice=JSON.parse(localStorage.getItem('hocco-city')||'{}');selectedCity=choice.city||'';selectedUF=choice.uf||''}catch{}
const offerAvailable=s=>!s.offer_expires_on||s.offer_expires_on>=new Intl.DateTimeFormat('en-CA',{timeZone:'America/Sao_Paulo',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const normalizeCity=x=>String(x||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim();
const token=()=>Array.from(crypto.getRandomValues(new Uint8Array(32))).map(x=>x.toString(16).padStart(2,'0')).join('');
const toast=t=>{const e=document.querySelector('#toast');e.textContent=t;e.classList.add('show');clearTimeout(timer);timer=setTimeout(()=>e.classList.remove('show'),4200)};
const state=()=>{const p=location.hash.slice(1).split('/');return p[0]==='novo'?{page:'novo',renewal:p[1]||''}:p[0]==='pedido'&&p.length===3?{page:'pedido',code:p[1],key:p[2]}:p[0]==='empresa'&&p[1]?{page:'empresa',id:p[1]}:{page:'home'}};
const normalizeCnpj=value=>String(value||'').toUpperCase().replace(/[^A-Z0-9]/g,'').slice(0,14);
function validCnpj(value){const cnpj=normalizeCnpj(value);if(!/^[A-Z0-9]{12}[0-9]{2}$/.test(cnpj)||/^(.)\1{13}$/.test(cnpj))return false;const nums=[...cnpj].map(c=>c.charCodeAt(0)-48),digit=(chars,weights)=>{const rest=chars.reduce((sum,n,i)=>sum+n*weights[i],0)%11;return rest<2?0:11-rest};return nums[12]===digit(nums.slice(0,12),[5,4,3,2,9,8,7,6,5,4,3,2])&&nums[13]===digit(nums.slice(0,13),[6,5,4,3,2,9,8,7,6,5,4,3,2])}
function formatCnpj(value){const c=normalizeCnpj(value);return c.slice(0,2)+(c.length>2?'.'+c.slice(2,5):'')+(c.length>5?'.'+c.slice(5,8):'')+(c.length>8?'/'+c.slice(8,12):'')+(c.length>12?'-'+c.slice(12,14):'')}
async function load(){catalog=await api('sponsor.catalog')}
function home(){
 app.classList.remove('sponsor-detail-open');
 const rows=catalog.active||[],categories=[...new Set(rows.map(s=>s.category||'Outros'))];
 app.innerHTML=`<section class="sponsor-directory" id="patrocinadores"><div class="sponsor-directory-heading"><div><div class="eyebrow">Comunidade HOCCO</div><h1>Conheça quem <em>financia</em></h1><p class="subheading">Marcas que fazem parte da história da HOCCO.</p></div><a class="btn sponsor-join" href="#novo">Sua marca pode fazer parte <span aria-hidden="true">→</span></a></div><div class="location-filters"><div class="field"><label for="directory-city">Sua cidade</label><input id="directory-city" maxlength="80" list="sponsor-cities" placeholder="Escolha ou digite sua cidade" value="${esc(selectedCity)}"><datalist id="sponsor-cities">${[...new Set(rows.map(x=>x.city).filter(Boolean))].map(city=>`<option value="${esc(city)}"></option>`).join('')}</datalist></div><div class="field"><label for="directory-uf">UF</label><select id="directory-uf"><option value="">Todas</option>${UFS.map(uf=>`<option ${uf===selectedUF?'selected':''}>${uf}</option>`).join('')}</select></div><button class="btn secondary small" id="clear-location" type="button">Todas as cidades</button></div><p class="hint" id="directory-result" role="status"></p><div class="sponsor-category-filters" aria-label="Filtrar empresas por categoria"><button class="sponsor-filter is-active" type="button" data-sponsor-filter="Todas">Todas</button>${categories.map(c=>`<button class="sponsor-filter" type="button" data-sponsor-filter="${esc(c)}">${esc(c)}</button>`).join('')}</div>${rows.length?`<div class="sponsor-directory-grid">${rows.map(s=>`<a class="sponsor-directory-card" href="#empresa/${encodeURIComponent(s.id)}" data-city="${esc(s.city||'')}" data-uf="${esc(s.state_code||'')}" data-category="${esc(s.category||'Outros')}" aria-label="Ver detalhes de ${esc(s.company_name)}"><div class="sponsor-cover-wrap"><img class="sponsor-cover" src="${esc(s.cover_url||s.logo_url)}" alt="Capa de ${esc(s.company_name)}" loading="lazy" referrerpolicy="no-referrer"><span class="sponsor-category-tag">${esc(s.category||'Outros')}</span></div><div class="sponsor-directory-content"><img class="sponsor-avatar" src="${esc(s.logo_url)}" alt="Logo de ${esc(s.company_name)}" loading="lazy" referrerpolicy="no-referrer"><strong>${esc(s.company_name)}</strong><small>${esc(s.city? s.city+' / '+s.state_code:'Localidade não informada')}</small><p>${esc(s.company_description||'Conheça esta marca parceira da comunidade HOCCO.')}</p>${s.community_offer&&offerAvailable(s)?`<span class="sponsor-offer"><span aria-hidden="true">◆</span> ${esc(s.community_offer)}</span>`:''}<span class="sponsor-card-action">Ver perfil <span aria-hidden="true">→</span></span></div></a>`).join('')}</div>`:'<div class="empty"><h3>As primeiras marcas vêm aí.</h3><p>Em breve você poderá conhecer as empresas que apoiam a HOCCO.</p></div>'}<div class="sponsor-directory-foot"><span>Uma comunidade que cresce junto com quem acredita nela.</span><a href="#novo">Apresentar minha empresa →</a></div></section><section class="sponsor-faq"><h2>Como funciona?</h2><p>As marcas exibidas passaram pela curadoria e tiveram o pagamento confirmado. Ao abrir um perfil, você confere a empresa, a descrição e qualquer oferta aprovada antes de decidir se quer acessar o site ou perfil externo.</p><p>A presença dura sete dias consecutivos. A contratação é avulsa, sem cobrança recorrente.</p><p>Quer apresentar sua marca à comunidade? <a href="#novo">Inscreva sua empresa para análise.</a></p></section>`;
 let selectedCategory='Todas';
 const applyFilters=()=>{selectedCity=document.querySelector('#directory-city').value.trim();selectedUF=document.querySelector('#directory-uf').value;let visible=0;document.querySelectorAll('.sponsor-directory-card').forEach(card=>{const match=(!selectedCity||normalizeCity(card.dataset.city)===normalizeCity(selectedCity))&&(!selectedUF||card.dataset.uf===selectedUF)&&(selectedCategory==='Todas'||card.dataset.category===selectedCategory);card.hidden=!match;if(match)visible++});document.querySelector('#directory-result').textContent=visible?visible+' empresa(s) encontrada(s).':'Ainda não há patrocinadores nesta seleção. Você pode consultar outras cidades.';try{localStorage.setItem('hocco-city',JSON.stringify({city:selectedCity,uf:selectedUF}))}catch{}};
 document.querySelectorAll('[data-sponsor-filter]').forEach(button=>button.addEventListener('click',()=>{selectedCategory=button.dataset.sponsorFilter;document.querySelectorAll('[data-sponsor-filter]').forEach(x=>x.classList.toggle('is-active',x===button));applyFilters()}));
 document.querySelector('#directory-city').addEventListener('input',applyFilters);document.querySelector('#directory-uf').addEventListener('change',applyFilters);document.querySelector('#clear-location').onclick=()=>{document.querySelector('#directory-city').value='';document.querySelector('#directory-uf').value='';applyFilters()};applyFilters();
 if(location.hash==='#patrocinadores')requestAnimationFrame(()=>document.querySelector('#patrocinadores')?.scrollIntoView({behavior:'smooth',block:'start'}));
}
function company(id){
 const s=(catalog.active||[]).find(x=>String(x.id)===decodeURIComponent(id));
 if(!s){location.hash='patrocinadores';return}
 app.classList.add('sponsor-detail-open');
 const panel=document.createElement('aside');panel.className='sponsor-detail-panel';panel.setAttribute('aria-labelledby','sponsor-detail-title');let linkHost='endereço indisponível';try{linkHost=new URL(s.destination_url).hostname}catch{};
 panel.innerHTML=`<button class="sponsor-detail-close" type="button" aria-label="Fechar perfil">×</button><img class="sponsor-detail-cover" src="${esc(s.cover_url||s.logo_url)}" alt="Capa de ${esc(s.company_name)}"><div class="sponsor-detail-body"><img class="sponsor-detail-avatar" src="${esc(s.logo_url)}" alt="Logo de ${esc(s.company_name)}"><h2 id="sponsor-detail-title">${esc(s.company_name)}</h2><span class="sponsor-detail-category">${esc(s.category||'Outros')} · ${esc(s.city?s.city+' / '+s.state_code:'Localidade não informada')}</span><p class="sponsor-detail-description">${esc(s.company_description||'Conheça esta marca parceira da comunidade HOCCO.')}</p>${s.community_offer&&offerAvailable(s)?`<div class="sponsor-detail-offer"><span class="offer-icon" aria-hidden="true">◆</span><div><strong>${esc(s.community_offer)}</strong><small>${esc(s.offer_conditions||'Confira as condições diretamente com a empresa antes de contratar.')}${s.offer_expires_on?' · Válida até '+esc(s.offer_expires_on.split('-').reverse().join('/')):''}</small></div></div>`:''}<p class="sponsor-link-check"><strong>Destino identificado</strong><br><span>${esc(linkHost)}</span><small>Link HTTPS. Confira o domínio antes de acessar; esta checagem não certifica a reputação da empresa ou do site.</small></p><a class="btn sponsor-visit" href="${esc(s.destination_url)}" target="_blank" rel="noopener noreferrer nofollow">Acessar empresa <span aria-hidden="true">↗</span></a><p class="sponsor-external-note">O link da empresa será aberto em uma nova aba.</p><a class="sponsor-return" href="#patrocinadores">← Voltar aos patrocinadores</a></div>`;
 app.append(panel);api('sponsor.event',{id:s.id,event:'profile'}).catch(()=>{});panel.querySelector('.sponsor-visit')?.addEventListener('click',()=>{api('sponsor.event',{id:s.id,event:'click'}).catch(()=>{})});
 document.querySelectorAll('.sponsor-directory-card').forEach(card=>{if(card.getAttribute('href')==='#empresa/'+encodeURIComponent(s.id))card.classList.add('is-selected')});
 const close=()=>{document.removeEventListener('keydown',onKey);location.hash='patrocinadores'},onKey=e=>{if(e.key==='Escape')close()};
 panel.querySelector('.sponsor-detail-close').onclick=close;panel.querySelector('.sponsor-visit')?.addEventListener('click',event=>{if(!confirm('Você está saindo da HOCCO para acessar '+linkHost+'. Confira o endereço na barra do navegador. Deseja continuar?'))event.preventDefault()});document.addEventListener('keydown',onKey);panel.querySelector('.sponsor-detail-close').focus()
}
function form(renewal=''){
 if(catalog.settings.enabled===false){app.innerHTML='<section class="narrow"><div class="empty"><h2>Inscrições de patrocinadores temporariamente fechadas.</h2><a class="btn" href="/ir-alem/">Voltar</a></div></section>';return}
 const priceCents=Number.isInteger(Number(catalog.settings.price_cents))?Number(catalog.settings.price_cents):2990;
 app.innerHTML=`<section class="sponsor-signup-layout">
  <aside class="sponsor-signup-story"><div class="eyebrow">Parcerias que fortalecem</div><h1>Sua marca perto da comunidade <em>HOCCO</em></h1>
   <p class="sponsor-story-lead">Apresente sua empresa para quem acompanha a HOCCO e faça parte da história que estamos construindo.</p>
   <div class="sponsor-process"><div><b>1</b><span><strong>Cadastro</strong><small>Conte quem é sua empresa.</small></span></div><i>→</i><div><b>2</b><span><strong>Pagamento</strong><small>Checkout seguro, uma única vez.</small></span></div><i>→</i><div><b>3</b><span><strong>Curadoria</strong><small>A marca só vai ao ar após aprovação.</small></span></div></div>
   <div class="sponsor-value-card"><span class="sponsor-value-icon">↗</span><p><strong>Uma semana para apresentar sua marca.</strong><br>Perfil com logo, capa, descrição e link por <strong>7 dias</strong>, após pagamento e aprovação da curadoria.</p></div>
   <div class="sponsor-security-note"><span>◈</span><p><strong>Curadoria após a confirmação do pagamento</strong><br>Conferimos CNPJ, identidade da marca, conteúdo e link antes de qualquer publicação. O pagamento não garante aprovação.</p></div>
   <p class="sponsor-price-note">Investimento desta semana <strong>${money(priceCents)}</strong><br><small>Pagamento único. Sem renovação automática.</small></p>
  </aside>
  <div class="sponsor-form-card"><div class="sponsor-form-progress"><div><span>Etapa 1 de 3</span><strong>Cadastro da empresa</strong></div><span class="sponsor-progress-track"><i></i></span></div>
   <div class="sponsor-form-title"><h2>Dados da empresa</h2><p>Preencha as informações para enviar sua marca à curadoria.</p></div>
   <form id="sponsor-form" novalidate>
    <div class="sponsor-field-grid">
     <div class="field"><label for="sponsor-cnpj">CNPJ <span>*</span></label><input id="sponsor-cnpj" name="cnpj" type="text" inputmode="text" autocomplete="organization" autocapitalize="characters" maxlength="18" placeholder="00.000.000/0000-00" required><small>Confira o número e os dígitos verificadores.</small></div>
     <div class="field"><label for="sponsor-legal-name">Razão social <span>*</span></label><input id="sponsor-legal-name" name="legalName" maxlength="160" autocomplete="organization" placeholder="Nome empresarial completo" required></div>
     <div class="field"><label for="sponsor-company-name">Nome fantasia <span>*</span></label><input id="sponsor-company-name" name="companyName" maxlength="80" placeholder="Como sua marca é conhecida" required></div>
     <div class="field"><label for="sponsor-contact-name">Responsável <span>*</span></label><input id="sponsor-contact-name" name="contactName" maxlength="80" autocomplete="name" placeholder="Nome completo" required></div>
     <div class="field"><label for="sponsor-email">E-mail empresarial <span>*</span></label><input id="sponsor-email" name="email" type="email" maxlength="254" autocomplete="email" placeholder="contato@suaempresa.com.br" required></div>
     <div class="field"><label for="sponsor-phone">WhatsApp</label><input id="sponsor-phone" name="phone" type="tel" autocomplete="tel" placeholder="(DDD) 99999-9999"><small>Usado para avisos somente se você autorizar.</small></div>
     <div class="location-filters"><div class="field"><label for="sponsor-city">Cidade da empresa *</label><input id="sponsor-city" name="city" maxlength="80" required placeholder="Ex.: Bauru"></div><div class="field"><label for="sponsor-state">UF *</label><select id="sponsor-state" name="stateCode" required><option value="">Selecione</option>${UFS.map(uf=>`<option>${uf}</option>`).join('')}</select></div></div>
     <div class="field"><label for="sponsor-category">Categoria <span>*</span></label><select id="sponsor-category" name="category" required><option value="">Selecione uma categoria</option><option>Alimentação e bebidas</option><option>Casa e construção</option><option>Educação e cultura</option><option>Moda e acessórios</option><option>Serviços</option><option>Tecnologia</option><option>Outros</option></select></div>
     <div class="field"><label for="sponsor-destination">Site ou perfil oficial <span>*</span></label><input id="sponsor-destination" name="destinationUrl" type="url" maxlength="2048" placeholder="https://www.suaempresa.com.br" required><small>O público verá este link antes de decidir se quer acessar.</small></div>
    </div>
    <div class="field sponsor-description-field"><label for="sponsor-description">Apresente sua empresa <span>*</span></label><textarea id="sponsor-description" name="companyDescription" maxlength="600" minlength="20" required placeholder="Conte em poucas linhas o que sua empresa oferece e o que a comunidade encontrará."></textarea><small>Essa descrição ficará no perfil público da empresa aprovada. De 20 a 600 caracteres.</small></div>
    <div class="sponsor-upload-grid"><div class="field"><label for="sponsor-logo">Logo da empresa <span>*</span></label><input name="logo" id="sponsor-logo" type="file" accept="image/png,image/jpeg,image/webp" required><small>PNG, JPG ou WebP · até 5 MB. A imagem é otimizada automaticamente no envio.</small><div id="logo-preview" class="logo-preview" hidden></div></div><div class="field"><label for="sponsor-cover">Imagem de capa <span>*</span></label><input name="cover" id="sponsor-cover" type="file" accept="image/png,image/jpeg,image/webp" required><small>PNG, JPG ou WebP · até 5 MB. A imagem é otimizada automaticamente no envio.</small><div id="cover-preview" class="logo-preview" hidden></div></div></div>
    <div class="field sponsor-offer-field"><label for="sponsor-offer">Oferta ou desconto para a comunidade <span>(opcional)</span></label><textarea id="sponsor-offer" name="communityOffer" maxlength="240" placeholder="Ex.: 10% de desconto para membros da comunidade HOCCO. Informe as condições e a validade."></textarea><small>A oferta será analisada e só aparecerá no perfil se for aprovada.</small></div>
    <div class="field"><label for="offer-conditions">Condições da oferta</label><textarea id="offer-conditions" name="offerConditions" maxlength="500" placeholder="Como usar o desconto, quem pode usar e restrições"></textarea></div><div class="field"><label for="offer-validity">Validade da oferta (opcional)</label><input id="offer-validity" name="offerExpiresOn" type="date"></div><div class="sponsor-notice-options"><strong>Avisos pelo WhatsApp (opcional)</strong><label class="check"><input name="thankYouOptIn" type="checkbox"><span>Quero receber agradecimentos do Alex Hocc a cada dois dias durante a semana do patrocínio.</span></label><label class="check"><input name="expiryNoticeOptIn" type="checkbox"><span>Quero receber um aviso antes do fim dos sete dias.</span></label></div>
    <label class="check sponsor-consent"><input name="terms" type="checkbox" required><span>Autorizo a análise dos dados empresariais enviados, confirmo que posso representar a empresa e aceito as <a href="/#patrocinadores" target="_blank" rel="noopener">regras de patrocínio</a> e a <a href="/#privacidade" target="_blank" rel="noopener">política de privacidade</a>. Entendo que o pagamento é feito antes da curadoria e que pagar não garante aprovação nem publicação.</span></label>
    <div class="sponsor-form-actions"><p>Após enviar, você segue para o checkout seguro. A curadoria analisa a empresa depois da confirmação do pagamento.</p><button class="btn" id="sponsor-submit" type="submit">Cadastrar e ir para pagamento <span>→</span></button></div><div id="form-error" class="error" role="alert" aria-live="polite"></div>
   </form>
  </div>
 </section>`;
 const cnpjInput=document.querySelector('#sponsor-cnpj');
 cnpjInput.addEventListener('input',()=>{const next=formatCnpj(cnpjInput.value);if(next!==cnpjInput.value){cnpjInput.value=next;cnpjInput.setSelectionRange(next.length,next.length)}});
 if(renewal){try{const r=JSON.parse(sessionStorage.getItem('hocco-sponsor-renewal')||'{}');document.querySelector('[name=cnpj]').value=formatCnpj(r.cnpj||'');document.querySelector('[name=legalName]').value=r.legal_name||'';document.querySelector('[name=companyName]').value=r.company_name||'';document.querySelector('[name=category]').value=r.category||'Outros';document.querySelector('[name=city]').value=r.city||'';document.querySelector('[name=stateCode]').value=r.state_code||'';document.querySelector('[name=offerConditions]').value=r.offer_conditions||'';document.querySelector('[name=offerExpiresOn]').value=r.offer_expires_on||'';document.querySelector('[name=companyDescription]').value=r.company_description||'';document.querySelector('[name=contactName]').value=r.contact_name||'';document.querySelector('[name=email]').value=r.email||'';document.querySelector('[name=phone]').value=r.phone||'';document.querySelector('[name=destinationUrl]').value=r.destination_url||'';document.querySelector('[name=communityOffer]').value=r.community_offer||''}catch{}}
 let previewUrls={};
 for(const[inputId,previewId,label]of[['sponsor-logo','logo-preview','logo'],['sponsor-cover','cover-preview','capa']])document.querySelector('#'+inputId).addEventListener('change',()=>{const input=document.querySelector('#'+inputId),file=input.files[0],preview=document.querySelector('#'+previewId);if(previewUrls[label]){URL.revokeObjectURL(previewUrls[label]);delete previewUrls[label]}if(!file){preview.hidden=true;return}if(file.size>5*1024*1024){document.querySelector('#form-error').textContent='Cada imagem pode ter até 5 MB.';input.value='';preview.hidden=true;return}if(!['image/png','image/jpeg','image/webp'].includes(file.type)){document.querySelector('#form-error').textContent='Use imagens em PNG, JPG ou WebP.';input.value='';preview.hidden=true;return}document.querySelector('#form-error').textContent='';previewUrls[label]=URL.createObjectURL(file);preview.innerHTML='<img alt="Prévia de '+label+'" src="'+previewUrls[label]+'"><span>'+esc(file.name)+'</span>';preview.hidden=false});
 const optimizeImage=async file=>{if(file.size>5*1024*1024)throw Error('Cada imagem pode ter até 5 MB.');const bitmap=await createImageBitmap(file);let scale=Math.min(1,1800/Math.max(bitmap.width,bitmap.height));for(let pass=0;pass<10;pass++){const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(bitmap.width*scale));canvas.height=Math.max(1,Math.round(bitmap.height*scale));const context=canvas.getContext('2d',{alpha:true});if(!context)throw Error('Não foi possível preparar uma das imagens.');context.drawImage(bitmap,0,0,canvas.width,canvas.height);for(const quality of[.86,.76,.66,.56,.48]){const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/webp',quality));if(blob&&blob.size<=850*1024&&['image/png','image/jpeg','image/webp'].includes(blob.type)){bitmap.close();return{blob,mime:blob.type}}}scale*=.82}bitmap.close();throw Error('Não foi possível otimizar a imagem. Escolha uma foto com menor resolução.')};
 const toBase64=blob=>new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=()=>reject(Error('Não foi possível ler uma das imagens.'));reader.readAsDataURL(blob)});
 document.querySelector('#sponsor-form').addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.currentTarget),submit=document.querySelector('#sponsor-submit'),error=document.querySelector('#form-error'),cnpj=normalizeCnpj(f.get('cnpj')),logo=f.get('logo'),cover=f.get('cover');error.textContent='';if(!validCnpj(cnpj)){error.textContent='Confira o CNPJ e seus dígitos verificadores.';document.querySelector('#sponsor-cnpj').focus();return}if(!(logo instanceof File)||!logo.size||!(cover instanceof File)||!cover.size){error.textContent='Anexe o logo e a foto de capa para continuar.';return}if(logo.size>5*1024*1024||cover.size>5*1024*1024){error.textContent='Cada imagem pode ter até 5 MB.';return}submit.disabled=true;submit.textContent='Otimizando imagens…';try{const[logoImage,coverImage]=await Promise.all([optimizeImage(logo),optimizeImage(cover)]),[logoBase64,coverBase64]=await Promise.all([toBase64(logoImage.blob),toBase64(coverImage.blob)]),offer=String(f.get('communityOffer')||'').trim();submit.textContent='Preparando pagamento…';const d=await api('sponsor.create',{cnpj,legalName:f.get('legalName'),companyName:f.get('companyName'),category:f.get('category'),city:f.get('city'),stateCode:f.get('stateCode'),offerConditions:f.get('offerConditions'),offerExpiresOn:f.get('offerExpiresOn'),companyDescription:f.get('companyDescription'),contactName:f.get('contactName'),email:f.get('email'),phone:f.get('phone'),logoMime:logoImage.mime,logoBase64,coverMime:coverImage.mime,coverBase64,destinationUrl:f.get('destinationUrl'),offerEnabled:offer.length>0,communityOffer:offer,thankYouOptIn:f.has('thankYouOptIn'),expiryNoticeOptIn:f.has('expiryNoticeOptIn'),terms:f.has('terms'),publication:f.has('terms'),sponsorTermsVersion:'2026-10-19.patrocinio.v3',renewalOf:renewal||null,trackingToken:token()});location.hash='pedido/'+d.sponsor.code+'/'+d.trackingToken}catch(x){error.textContent=x.message;submit.disabled=false;submit.innerHTML='Continuar para pagamento <span aria-hidden="true">→</span>'}});
}
async function order(code,key){app.innerHTML='<div class="empty">Consultando seu patrocínio…</div>';try{const d=await api('sponsor.lookup',{code,trackingToken:key}),s=d.sponsor,pay=!s.payment_hold&&s.review!=='rejected'&&s.payment==='pending';try{sessionStorage.setItem('hocco-sponsor-renewal',JSON.stringify({id:s.id,city:s.city,state_code:s.state_code,offer_conditions:s.offer_conditions,offer_expires_on:s.offer_expires_on,company_name:s.company_name,category:s.category||'Outros',company_description:s.company_description||'',logo_url:s.logo_url,cover_url:s.cover_url,destination_url:s.destination_url,contact_name:d.contact.contact_name,email:d.contact.email,phone:d.contact.phone,cnpj:d.contact.cnpj,legal_name:d.contact.legal_name,community_offer:s.community_offer||''}));}catch{}app.innerHTML='<section class="narrow sponsor-tracking"><div class="eyebrow">Acompanhamento privado</div><h1 class="section-title">'+esc(s.company_name)+'<br><em>'+(s.payment==='confirmed'?(s.review==='approved'?'na HOCCO.':s.review==='rejected'?'solicitação encerrada.':'na fila da curadoria.'):(s.payment==='refunded'?'com devolução registrada.':'aguardando pagamento.'))+'</em></h1><div class="paper"><div class="row wrap"><strong>Categoria</strong><span class="badge">'+esc(s.category||'Outros')+'</span></div><div class="row wrap" style="margin-top:14px"><strong>Curadoria</strong><span class="badge '+(s.review==='rejected'?'red':s.review==='approved'?'success':'orange')+'">'+(s.review==='pending'?(s.payment==='confirmed'?'Em curadoria':'Aguardando pagamento'):s.review==='approved'?'Aprovado':'Não aprovado')+'</span></div><div class="row wrap" style="margin-top:14px"><strong>Pagamento</strong><span class="badge">'+(s.payment==='confirmed'?'Confirmado':s.payment==='refunded'?'Devolvido':'Aguardando')+'</span></div>'+(s.reason?'<div class="note" style="margin-top:17px">Motivo: '+esc(s.reason)+'</div>':'')+(s.community_offer?'<div class="note" style="margin-top:17px"><strong>Oferta à comunidade:</strong> '+esc(s.community_offer)+'</div>':'')+(s.expires_at?'<div class="note" style="margin-top:17px">Patrocínio ativo até <strong>'+esc(new Date(s.expires_at).toLocaleString('pt-BR'))+'</strong>. A renovação é manual.</div>':'')+'<p class="hint" style="margin-top:18px">Código '+esc(s.code)+' · guarde este link privado.</p></div>'+(s.review==='pending'?'<div class="note sponsor-curation-note">'+(s.payment==='confirmed'?'Sua empresa está na fila da curadoria. O pagamento não garante aprovação; se aprovada, a publicação começa após a análise e a liberação de uma vaga.':'A curadoria começa após a confirmação do pagamento. Em seguida, a equipe analisa sua empresa. O pagamento não garante aprovação nem publicação.')+'</div>':'')+(s.review==='rejected'&&s.payment==='confirmed'?'<div class="note sponsor-curation-note">Sua solicitação não foi aprovada. A devolução integral está sendo encaminhada pelo mesmo meio de pagamento; atualize o acompanhamento para conferir o status.</div>':'')+(s.review==='rejected'&&s.payment==='refunded'?'<div class="note sponsor-curation-note">Sua solicitação não foi aprovada e a devolução foi registrada. O prazo de crédito depende do meio de pagamento.</div>':'')+(pay?paymentCard({kind:'sponsor',title:'Sua marca está pronta para a análise',product:'Patrocínio HOCCO',detail:'7 dias · contratação avulsa · sem cobrança recorrente',amount:s.price_cents,buttonId:'mp-checkout-sponsor',buttonLabel:'Quero apresentar minha marca',help:'O checkout aceita Pix ou cartão, mesmo sem conta no Mercado Pago. O QR Code Pix aparece no ambiente seguro.',note:'Após a confirmação do Mercado Pago, sua empresa entra na curadoria. A publicação depende da aprovação e de vaga disponível.'}):paymentFeedback(s,'sponsor'))+(s.payment_claimed?'<div class="note">Pagamento informado. A equipe fará a conferência.</div>':'')+'<div class="sponsor-actions"><button class="btn secondary" id="refresh-sponsor">Atualizar status</button>'+(s.payment==='confirmed'&&s.expires_at&&Date.parse(s.expires_at)>Date.now()?'<a class="btn" href="#novo/'+esc(s.id)+'">Renovar mais 7 dias</a>':'<a class="btn ghost" href="#novo">Pedir outra semana</a>')+'<a class="btn ghost" href="/">Voltar ao Message</a></div><p class="hint">O período começa após aprovação e confirmação do pagamento. Ao final de 7 dias a vaga fica livre; não precisa fazer nada para encerrar.</p></section>';document.querySelector('#refresh-sponsor').onclick=()=>order(code,key);document.querySelector('#mp-checkout-sponsor')?.addEventListener('click',async e=>{const button=e.currentTarget;button.disabled=true;button.textContent='Abrindo checkout…';try{const result=await api('payment.checkout',{kind:'sponsor',code,trackingToken:key});location.assign(result.checkoutUrl)}catch(error){button.disabled=false;button.textContent='Pagar com Pix ou cartão · '+money(s.price_cents);toast(error.message)}});}catch(e){app.innerHTML='<section class="narrow"><div class="empty"><h2>Não foi possível abrir esse acompanhamento.</h2><p>'+esc(e.message)+'</p><a class="btn" href="/ir-alem/">Voltar ao Ir Além</a></div></section>'}}
async function render(){try{if(!catalog)await load()}catch(e){app.innerHTML='<div class="empty"><h2>Serviço temporariamente indisponível.</h2><p>'+esc(e.message)+'</p><button class="btn" id="retry">Tentar novamente</button></div>';document.querySelector('#retry').onclick=()=>{catalog=null;render()};return}const s=state();if(s.page==='novo')return form(s.renewal);if(s.page==='pedido')return order(s.code,s.key);home();if(s.page==='empresa')company(s.id)}
let previousSponsorPage=state().page;
function transitionSponsorScreen(){
 const nextPage=state().page,direction=nextPage==='home'&&previousSponsorPage!=='home'?'back':'forward';previousSponsorPage=nextPage;
 if(matchMedia('(prefers-reduced-motion: reduce)').matches){render();return}
 if(typeof document.startViewTransition==='function'){
  document.documentElement.dataset.hoccoDirection=direction;
  const transition=document.startViewTransition(()=>render());
  transition.finished.then(()=>delete document.documentElement.dataset.hoccoDirection,()=>delete document.documentElement.dataset.hoccoDirection);
  return;
 }
 const className=direction==='back'?'screen-swipe-back':'screen-swipe-forward';app.classList.remove('screen-swipe-back','screen-swipe-forward');app.classList.add(className);render();
 setTimeout(()=>app.classList.remove(className),520);
}
window.addEventListener('hashchange',transitionSponsorScreen);setInterval(()=>{if(document.hidden)return;if(state().page==='home'){catalog=null;render()}else if(state().page==='pedido'){const page=state();api('payment.refresh',{kind:'sponsor',code:page.code,trackingToken:page.key}).catch(()=>{}).finally(()=>{if(location.hash==='#pedido/'+page.code+'/'+page.key)render()})}},30000);render();
